-- Contenu des duels : 30 ligues, les adversaires simulés et les questions de la bêta (anglais).
-- Fichier généré par scripts/build_duels_seed.py depuis content/duels : ne pas le modifier à la main.
-- Rejouable : chaque ligne est insérée ou mise à jour.

ON CONFLICT (position) DO UPDATE SET slug = EXCLUDED.slug, name = EXCLUDED.name, min_trophies = EXCLUDED.min_trophies, background_url = EXCLUDED.background_url, thumb_url = EXCLUDED.thumb_url, accent_hex = EXCLUDED.accent_hex;

ON CONFLICT (handle) DO UPDATE SET country_code = EXCLUDED.country_code, avatar_id = EXCLUDED.avatar_id;

ON CONFLICT (id) DO UPDATE SET lang = EXCLUDED.lang, level = EXCLUDED.level, kind = EXCLUDED.kind, subject = EXCLUDED.subject, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, image_url = EXCLUDED.image_url, image_credit = EXCLUDED.image_credit, slider_min = EXCLUDED.slider_min, slider_max = EXCLUDED.slider_max, slider_step = EXCLUDED.slider_step, correct_value = EXCLUDED.correct_value, unit = EXCLUDED.unit;
